def predicates(tree: TreeNode) -> List[Predicate]:
    """Return every Predicate in the tree (nested traversal)."""
    out: List[Predicate] = []
    _predicate_classes = (
        Comparison,
        Equality,
        TypeQuery,
        TypeAssertion,
        DegreeQuery,
        MinimalSufficiency,
        SetRestriction,
        BoundaryCase,
        Contrast,
        Causation,
        ClauseCoordination,
        Conditional,
        Temporal,
        RelativeRestriction,
        Control,
        Event,
    )

